  "claims": [
    {
      "claim": "The query is the sulfonylurea glibenclamide/glyburide; the closest supplied empirical anchor, glimepiride, has L1 absolute oral bioavailability of 97% (90% CI 93-102%) and is repeatedly reported as ~100% in humans, directly supporting F >= 20% for this chemotype.",
      "card_ids": ["C18","C36","C10","C13","C25","C26","C35","C38","C03","C22"]
    },
    {
      "claim": "L4 adds human fraction-absorbed and permeability evidence for the close sulfonylurea analog glipizide: FA >95% with high passive permeability (C144) and Caco-2 exsorptive Papp ~9.9 x 10^-6 cm/s under BCRP inhibition (C179), supporting efficient intestinal absorption for the shared phenethyl-sulfonylurea-cyclohexyl core.",
      "card_ids": ["C144","C179"]
    },
    {
      "claim": "L5 shows that the close sulfonylurea analog gliquidone is a P-gp/BCRP substrate (C208, C237) and that verapamil inhibits its secretory transport (C208); this is mechanistic evidence for possible efflux-mediated presystemic loss, but it is not a direct F measurement and does not affirm F < 20% for the query.",
      "card_ids": ["C208","C237"]
    },
    {
      "claim": "Low aqueous solubility records for glimepiride/glipizide do not affirm F < 20% because these same compounds have high human F/FA; solubility is formulation-dependent and not a threshold-relevant negative for the query.",
      "card_ids": ["C160","C174","C176","C150","C164","C145","C169","C144","C18","C36"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C208","C237"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query (glibenclamide/glyburide) is supplied; extrapolation relies on close glimepiride and glipizide analogs.",
    "No query-specific gut-wall efflux or intestinal-metabolism data; L5 records are for gliquidone, talinolol, sulpiride, tolbutamide, and other molecules.",
    "No query-specific first-pass hepatic metabolism or systemic clearance data; glyburide may differ from glimepiride in metabolism.",
    "No query formulation, dose, or food-effect data; low aqueous solubility of sulfonylureas is formulation-dependent.",
    "P-gp/BCRP substrate status of gliquidone is mechanistic and not a direct F result; transferability to glyburide is uncertain."
  ],
  "decision_summary": "L5 adds mechanistic gut-wall efflux evidence showing the close sulfonylurea analog gliquidone is a P-gp/BCRP substrate, but this is not a direct F measurement and does not affirm F < 20%; the direct glimepiride L1 absolute-F evidence (97-100%) and glipizide FA >95% remain decisive. Prediction remains high; confidence high; revision kept."
}

